export function sourceLanguage(text){if(/[\u3040-\u30ff]/u.test(text))return'ja';if(/[\uac00-\ud7af]/u.test(text))return'ko';if(/[\u4e00-\u9fff]/u.test(text))return'zh-CN';if(/[\u0400-\u04ff]/u.test(text))return'ru';if(/[\u0600-\u06ff]/u.test(text)&&!/[A-Za-z]{12}/u.test(text))return'ar';return'en'}
export function byteChunks(text,max=450){const chunks=[];let current='';const enc=new TextEncoder();for(const c of text){if(enc.encode(current+c).length>max){const lastSpace=Math.max(current.lastIndexOf(' '),current.lastIndexOf('\n'));if(lastSpace>current.length/2){chunks.push(current.slice(0,lastSpace+1));current=current.slice(lastSpace+1)+c}else{if(current)chunks.push(current);current=c}}else current+=c}if(current)chunks.push(current);return chunks;}
export function arabicLanguage(lang){return({JavaScript:'جافاسكربت',TypeScript:'تايب سكربت',Python:'بايثون',Rust:'رست',Go:'جو',Java:'جافا',Kotlin:'كوتلن',Dart:'دارت',Swift:'سويفت',Shell:'أوامر النظام',HTML:'لغة صفحات الويب',CSS:'تنسيق الويب',C:'سي','C++':'سي بلس بلس','C#':'سي شارب',PHP:'بي إتش بي',Ruby:'روبي',Vue:'فيو',JupyterNotebook:'دفاتر برمجية','Jupyter Notebook':'دفاتر برمجية',Markdown:'مستندات نصية',PowerShell:'باور شل',Dockerfile:'إعداد الحاويات',CMake:'إعداد البناء',R:'آر',Scala:'سكالا',Elixir:'إليكسير',Lua:'لوا',Haskell:'هاسكل',Svelte:'سفلت',Clojure:'كلوجر',ObjectiveC:'أوبجكتف سي','Objective-C':'أوبجكتف سي',TeX:'تنضيد المستندات',VimScript:'إعداد المحرر',Vim:'إعداد المحرر',Nix:'نيكس',Assembly:'أسمبلي'})[lang]||'لغة تقنية أخرى'}
export function decodeEntities(text){let out=String(text||'');for(let n=0;n<2;n++)out=out.replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos|nbsp);/gi,(whole,key)=>{const common={amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:' '};if(key[0]!=='#')return common[key.toLowerCase()]||whole;const number=key[1]?.toLowerCase()==='x'?parseInt(key.slice(2),16):parseInt(key.slice(1),10);return Number.isFinite(number)&&number>0&&number<=0x10ffff&&!(number>=0xd800&&number<=0xdfff)?String.fromCodePoint(number):''});return out}
function inlineText(text,depth=0){if(depth>5)return text;let out='';for(let i=0;i<text.length;){const image=text[i]==='!'&&text[i+1]==='[';const first=image?i+1:i;if(text[first]!=='['){out+=text[i++];continue}let count=1,j=first+1;for(;j<text.length&&count;j++){if(text[j]==='[')count++;if(text[j]===']')count--}if(count){out+=text[i++];continue}const label=text.slice(first+1,j-1);let end=j;if(text[j]==='('){let parens=1;j++;for(;j<text.length&&parens;j++){if(text[j]==='(')parens++;if(text[j]===')')parens--}if(parens){out+=text[i++];continue}end=j}else if(text[j]==='['){const k=text.indexOf(']',j+1);if(k>=0)end=k+1}else{out+=text[i++];continue}if(!image)out+=inlineText(label,depth+1);i=end}return out}
export function cleanTranslation(text){return decodeEntities(text).replace(/^\s*[)\]([#*_`|!<>;]+\s*$/gm,'').replace(/\n{3,}/g,'\n\n').trim()}
export function plainReadme(text){let out=decodeEntities(text).replace(/<!--[\s\S]*?-->/g,'').replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi,'').replace(/```[\s\S]*?```/g,'\n').replace(/~~~[\s\S]*?~~~/g,'\n').replace(/^ {4}[^\n]+$/gm,'').replace(/^\s*\[[^\]]+\]:[^\n]*$/gm,'');out=inlineText(out).replace(/<[^>]*>/g,'').replace(/https?:\/\/\S+/g,'').replace(/`([^`]+)`/g,'$1').replace(/\*\*|__/g,'').replace(/^[ \t]*[#>*-]+[ \t]*/gm,'').replace(/^[ \t]*\|?[ \t]*:?-{3,}[^\n]*$/gm,'').replace(/\|/g,' — ');return cleanTranslation(out)}
export function safePublicURL(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null}catch{return null}}
export function safeAssetURL(value,fullName){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='github.com'&&u.pathname.startsWith('/'+fullName+'/releases/download/')?u.href:null}catch{return null}}
export function createTranslator({fetcher=globalThis.fetch,storage,clock=()=>Date.now()}={}){if(storage===undefined){try{storage=globalThis.localStorage}catch{}}const inFlight=new Map();let quotaBlocked=false;const queue=[];let active=0;const cacheKey='radar-ar-v2';let cache={};try{cache=JSON.parse(storage?.getItem(cacheKey)||'{}')}catch{}if(!cache||typeof cache!=='object')cache={};
function schedule(fn){return new Promise((resolve,reject)=>{queue.push({fn,resolve,reject});pump()})}function pump(){if(active>=2||!queue.length)return;const job=queue.shift();active++;Promise.resolve().then(job.fn).then(job.resolve,job.reject).finally(()=>{active--;pump()})}
function saved(k){const v=cache[k];return v&&typeof v.ar==='string'&&v.at>clock()-30*86400000?v.ar:null}
async function translate(text,language=sourceLanguage(text)){text=String(text||'').trim();if(!text)return'';if(language==='ar')return text;const key=language+'|'+text;const hit=saved(key);if(hit)return hit;if(inFlight.has(key))return inFlight.get(key);const task=schedule(async()=>{if(quotaBlocked)throw new Error('وصلت خدمة الترجمة لحد الاستخدام. النصوص المترجمة سابقًا متاحة.');let parts=[];for(const part of byteChunks(text)){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),14000);try{const url=new URL('https://api.mymemory.translated.net/get');url.search=new URLSearchParams({q:part,langpair:language+'|ar'});const response=await fetcher(url,{signal:controller.signal});if(!response.ok)throw new Error('خدمة الترجمة غير متاحة الآن.');const data=await response.json();if(data.quotaFinished||Number(data.responseStatus)===429){quotaBlocked=true;throw new Error('وصلت خدمة الترجمة لحد الاستخدام. أعد المحاولة لاحقًا.')}if(Number(data.responseStatus)!==200||!data.responseData?.translatedText)throw new Error('لم تتوفر ترجمة عربية موثوقة لهذا النص.');const value=data.responseData.translatedText;if(/MYMEMORY WARNING|QUERY LENGTH LIMIT|INVALID SOURCE|SELECT TWO DISTINCT/i.test(value))throw new Error('تعذر ترجمة النص. جرّب تحديد اللغة من صفحة التفاصيل.');parts.push(value)}catch(error){if(error.name==='AbortError')throw new Error('تأخرت خدمة الترجمة. جرّب مجددًا.');throw error}finally{clearTimeout(timer)}}const result=cleanTranslation(parts.join(' '));if(!/[\u0600-\u06ff]/u.test(result))throw new Error('النتيجة لا تحتوي على شرح عربي. جرّب لغة المصدر المناسبة.');cache[key]={ar:result,at:clock()};const entries=Object.entries(cache);if(entries.length>300)cache=Object.fromEntries(entries.slice(-300));try{storage?.setItem(cacheKey,JSON.stringify(cache))}catch{}return result;});inFlight.set(key,task);try{return await task}finally{inFlight.delete(key)}}
return{translate,peek:(text,language=sourceLanguage(text))=>saved(language+'|'+String(text||'').trim()),resetQuota:()=>{quotaBlocked=false}};}
